add('operational-model','Global party. Federated relationships.','Operational model / Edition 05','Two independent distribution paths on top of one coherent party relationship model.',
'<div class="link-grid"><a href="'+monitor+'#business"><span>INTERACTIVE MODEL</span><h3>Inspect the business tables →</h3><p>Table defaults, major keys and separate sovereignty bindings.</p></a><a href="'+monitor+'#services"><span>BUSINESS SERVICE LAB</span><h3>Run a transaction →</h3><p>Contact changes, consent withdrawal, new holdings and table/key overrides.</p></a></div>'+
section('Keep identity distribution separate from relationship access',table(['Path','Distribution key','Approved payload','Seed behaviour'],[
['Global party minimum','Owner + party UUID','id, global_party_id, party_type','Aster: SG owner, GB and US recipients; Example Trading: US excluded.'],['Relationship graph','Owner + relationship UUID','Whitelisted, dependency-closed rows','Personal → LE-GB-02 contact; business → LE-GB-03 minimal; both exclude US.'],['Holding restriction','Owner + holding UUID','Narrowing rule on resource and children','Restricted holding and its assignment are removed without dangling child references.']]))+
call('Global is an intent, not an exemption','A global party row remains identifying metadata. It requires explicit identity-resolution grants and approved physical placement. A shared global identity does not make a contact, relationship link, account identifier or product holding global. In this fixture three recipient grants illustrate all three physical stores; there is no blanket entitlement for all 30 entities.')+
section('The operational relationship model',erd+'<p>Two parties, two relationships and three initial holdings form the seed graph. Aster is a personal account holder and an authorised business signatory; the organisation is the business account owner. The same party and contact resources participate in multiple scopes. Foreign keys preserve ownership at source and ownership, scope and recipient at the destination.</p>')+
section('Table-by-table integration',table(['Business dataset','Major key','Default distribution','Enforcement'],[
[t,c['major_key'],c['default_mode'].replace('_',' '),'Owner-only' if c['owner_only'] else 'Contact profile + context consent + parent closure' if c['needs_contact_consent'] else 'Separate minimal party scope / key exclusion' if t=='party' else 'Scope grants + resource constraints + parent closure'] for t,c in model_spec['tables'].items()]))+
section('Source data remains operational','<p>The business schema contains party, relationship, party_relationship, product_holding, contact_info, consent, preference, contact_history, three typed alternate-ID tables and classification. owner_entity_id represents business custody. Destination lists, country exclusions, policy versions and delivery receipts are separate. The classification table contains assignments with exactly one typed party/relationship/holding reference; a managed taxonomy catalogue is a future service.</p>')+
section('Worked examples',table(['Change','Source effect','Federation effect'],[['Contact update','Contact row, selected preference and history update together','Both relationship scopes advance; global party stays unchanged.'],['Personal consent withdrawn','Only personal servicing EMAIL consent changes','Personal contact/preference rows removed; business minimal graph and owner contact remain.'],['Party excluded from US','Separate party resource rule changes','Global minimum is removed from US; all uses of the party inherit the exclusion.'],['Contact table made local','Separate table default narrows all contacts','All contact projections are removed; no business row is rewritten with a residency flag.'],['Holding classified restricted','Business classification plus decision revision','Only the affected holding and dependent rows are removed.']]))+
call('Coexistence with the earlier record sandbox','The original flat entity/customer records remain available for scenario generation. Their owner + global_customer_id key is a teaching fixture, not the normalized relationship key. New party and relationship scopes use independent UUIDs so several relationships for one party can coexist under the same legal entity.'),
prompt3+'Implement the typed relational model and independent party/relationship scopes. Preserve many-to-many party roles and three alternate-ID parent types. Bind shared resources without duplicating sovereignty flags into business rows. Test that US contains Aster’s party minimum but no relationship or contact, and that a party-key exclusion prevents even that minimum. Include model migrations and a graph fixture integrity validator.')
add('sovereignty-integration','A parallel control layer. Explicit joins.','Sovereignty integration / Edition 05','Table defaults establish the contract. Business keys and context determine which rows may cross.',
section('The two schemas meet at stable identities',table(['Schema / table','Purpose','Join contract'],[['business.*','Typed operational rows','(owner_entity_id, id)'],['sovereignty.table_rule','Narrowing table default','owner + registered table'],['sovereignty.scope','Party or relationship authority, grants, purpose and epochs','owner + root_type + root_id'],['sovereignty.binding','Many-to-many scope membership','owner + scope + resource_type + resource_id'],['sovereignty.resource_rule','Shared-resource geographic/profile constraints','owner + resource_type + resource_id'],['sovereignty.outbox / audit / command_receipt','Atomic export intent and business evidence','source transaction + scope + request ID'],['projection.* / manifest / inbox','Approved recipient graph and deduplication','owner + scope + destination + row ID']]))+
section('Resolve rules by intersection',flow([('Table contract','Registered columns and default mode, generic verified OPA bundle.'),('Scope policy','Party or relationship recipients, purpose and geography.'),('Resource rules','Party exclusions and holding restrictions cannot be broadened by another context.'),('Business context','Classification and purpose/channel/relationship consent narrow the result.'),('Connected manifest','Remove withheld fields and dependency orphans; commit atomically at recipient.')]))+
code('''# Rego decision input: supplied from trusted local tables, not HTTP caller claims
{
  "customer": "resolved scope policy and entity grants",
  "destination_entity": "trusted directory entry",
  "destination_store": "resolved physical location",
  "resources": [{
    "table": "contact_info",
    "row": {"id": "...", "party_id": "...", "channel": "EMAIL"},
    "scope_kind": "relationship",
    "table_rule": {"mode": "relationship_policy", "denied_countries": ["US"]},
    "rule": "resource hard constraints",
    "sensitivity": "INTERNAL",
    "contact_consent": true
  }]
}
# Result per row: allow, reason, approved fields. Dependency closure runs next.''','OPA input outline')+
section('Why a sidecar is not zero integration','<p>The operational writer calls a sovereignty hook within its existing database transaction. The hook registers new business resources, resolves affected scopes, advances versions and appends export intents. It does not call a remote policy service while holding the transaction. Every writer—including bulk import and future maintenance jobs—must follow this contract or be denied write credentials. A raw changefeed alone cannot infer relationship membership, contextual consent or an atomic multi-table view.</p><p>The polymorphic binding points to a typed resource registry and is checked by the application against the actual business table. The database enforces owner-aware parent references and scope keys, but cannot by itself prove that an arbitrary resource_type/resource_id pair exists in its named table. Production needs registry integrity checks and a fail-closed path for unregistered mutations.</p>')+
section('Policy precedence examples',table(['Table default','Key/context restriction','Result'],[['party: global minimum','Party P2 excludes US','No P2 identifier in US.'],['relationship: policy federation','Relationship R1 excludes US','A global party never imports R1 into US.'],['contact_info: relationship policy','R1 contact grant + EMAIL consent; PHONE has no consent','EMAIL only in R1 projection.'],['product_holding: relationship policy','Holding H1 classified RESTRICTED','H1 and dependent classification/alternate rows withheld.'],['contact_info: owner only','R1 has a contact entitlement','No contact export; grant cannot override table restriction.']]))+
section('Safe read and removal semantics','<p>data_version tracks ordinary business freshness. decision_revision changes on consent/classification. policy_generation changes on table/key controls. placement_version binds the recipient store. The harness checks current authority before serving a stored graph; mismatched authorisation or placement revisions block reads until reconciliation. Previously authorised data can remain physically present while ingress is paused, which the UI reports separately from access. Live projection removal does not certify audit, inbox, backup or legal-hold erasure.</p>')+
call('Source-side denial is deliberate','A never-authorised destination receives no customer-specific denial record or tombstone. A previously authorised destination may retain a governed receipt after removing its payload so replayed old work cannot resurrect a copy. Rule bundles can be generic and global; customer-linked control facts remain subject to residency.'),
prompt3+'Implement a reusable SovereigntyHook on the same local unit of work as business mutations. Resolve table registry, scopes and hard resource restrictions from trusted state. OPA must default-deny missing datasets/facts. Build a dependency-closed manifest and enforce recipient foreign keys, idempotent inbox and monotonically fenced versions. Test cross-scope contamination, table/key narrowing, consent per relationship/channel, missing parents and stale replay. Add direct-writer controls before claiming parallel sovereignty is complete.')
add('service-transactions','Local business commit. Independent federation.','Business APIs & transactions / Edition 05','Deploy regional modular services behind regional gateways, with an explicit boundary between local success and remote delivery.',
section('Deployment and access',table(['Component','PoC now','Regional target'],[['Gateway','Loopback FastAPI endpoint; no authentication','Regional Envoy/Kong or equivalent + identity + local OPA admission + rate/size limits.'],['Business modules','Party, Contact/Consent, Relationship, Holdings, History in one process','Existing regional services with bounded sovereignty adapters; share a local UoW only where invariants require it, otherwise preserve explicit service consistency contracts.'],['Owner router','Trusted synthetic entity directory in harness','Resolve owner and physical home from authenticated context; reject or lawfully forward wrong-home request.'],['Policy/export worker','Local OPA + polling outbox','Local OPA; CDC outbox intents → regional Kafka → egress gate.'],['Recipient query/import','Single harness uses typed regional tables','Independent credentialed importer and query service; OPA admission, scopes and receipts.'],['Observability','OTel command, gate and import spans','Regional collectors, approved aggregates, governed audit archive.']]))+
call('No global body-terminating gateway by default','Regional gateways authenticate the caller and validate legal entity, service action and purpose. Forwarding customer payloads is itself governed processing. An independent global party service can expose only its approved minimum and must not reveal unauthorised relationship existence. The PoC deliberately does not implement these production authentication controls.')+
section('Follow one contact update',seq+'<p>Business success is returned after the owner transaction commits. The destination is eventually consistent. Reconciliation uses current authoritative facts and can coalesce earlier intents; it does not promise to deliver every intermediate business version.</p>')+
section('Concrete transaction boundaries',table(['Operation','One local transaction','Asynchronous follow-up'],[['Update contact','Contact + selected preference + history + both affected scope versions + outbox + audit + request receipt','Re-evaluate personal and business graphs independently; party minimum unchanged.'],['Open holding','Holding + owner-only alternate ID + classification + bindings/rules + scope version + intent','Export whitelisted holding fields; no balance or core identifier.'],['Withdraw consent','Relationship-specific consent + history + decision revision + intent','Read blocked against stale authorisation receipt; remove contact/preference projection.'],['Table/key restriction','Parallel control facts + affected epochs + intents + audit receipt','All affected scopes re-evaluated; global default cannot override denial.'],['Recipient replace','Delete child-first; insert parent-first; manifest + inbox + audit','Source acknowledgement recorded after destination commit.']]))+
section('API outline',table(['Endpoint','Contract'],[['GET /api/operational','Source graph, controls, typed destination rows, queue and receipts; owner-only diagnostic scope in production.'],['POST /api/operational/scopes/{id}/commands','request_id UUID, expected_version, command and synthetic fields; 409 stale version or conflicting replay.'],['GET /api/operational/scopes/{id}/preview/{entity}','Current actual OPA row decisions + dependency closure; read-only.'],['GET /api/operational/scopes/{id}/read/{entity}','Current purpose/entitlement/placement and decision epoch; then recipient graph.'],['POST /api/stores/{id}/pause','PoC fault injection for delayed import; not a production business endpoint.']]))+
section('Performance choices with explicit trade-offs','<p>The thin implementation replaces complete small graphs, polls every 800 ms and processes up to 15 operational deliveries per pass. It uses a single process lock, model scans and one source writer to make races reviewable. This is not a throughput design or benchmark. Production should use indexed binding lookups, bounded manifests, per-scope/destination partitions, local connection pooling, backpressure and retry budgets.</p><p>Very high party fanout should update a durable resource epoch and mark dependent scopes dirty in bounded batches. Reads must check the current resource authorisation epoch so delayed fanout cannot extend revoked access. Ordinary contact-value freshness may lag; consent/geography narrowing must fail closed. Keep WAN and policy transport outside local transactions and add serialization retry with idempotency.</p><p>Keep the transactional outbox as the business boundary. A future CockroachDB changefeed can publish outbox intents to regional Kafka. Changefeeds are at-least-once and do not preserve transaction-wide ordering; use a current connected manifest and an inbox rather than replaying unrelated table events as though they were atomic.</p>')+
section('Walkthrough and engineering gates',flow([('Global versus scoped','US sees Aster party minimum, no relationship. Example Trading party excluded.'),('Shared update','Change contact once; two relationship versions advance.'),('Revoke during pause','Pause London, withdraw consent, observe stored copy and denied read; resume removes rows.'),('Narrow by table or key','Owner-only contact table; party US exclusion; restricted holding.'),('Verify real adapters','Run SQL, OPA, crash/replay tests and inspect regional OTel. No inferred residency guarantee.')]))+
section('Validation and sources','<p>Executed: 840 operational browser/OPA cases (7,290 row decisions), Python graph/command tests, Node workflow tests and original 12 Rego / 990 entity parity checks. The subsequent unified Docker suite passed actual SQL commands/projections, API restart persistence and trace-correlated OTLP logs in Loki. The live Chromium walkthrough passed. The source supplies executable acceptance and typed SQL checks; database crash boundaries, accessibility, regional isolation and pilot load remain separate gates.</p>'+sources([('OPA policy language','https://www.openpolicyagent.org/docs/policy-language'),('CockroachDB changefeed delivery and ordering','https://docs.cockroachlabs.com/docs/stable/changefeed-messages'),('OpenTelemetry sensitive data handling','https://opentelemetry.io/docs/security/handling-sensitive-data/')])),
prompt3+'Start with the modular owner service, local ACID hook and current outbox poller. Add authenticated regional gateway adapters without routing payloads through an excluded geography. Implement bounded serializable retry and idempotency; fault-inject a source rollback, recipient crash and crash after destination commit before source acknowledgement. Verify stored-copy versus read-permission differences. Add regional OTel spans without party IDs/contact payloads. Only then replace poller with CDC/Kafka and partitioned workers; do not claim throughput without measurement.')
